pair A, P, S, C, Z, X;
C=(0,0);
Z=(1.732,0);
X=(3.732,0);
A=(4.732,0);
S=(1.732,1);
P=(3.732,1);
draw(A--X--Z--C--S--P--A);
draw(S--Z);
draw(P--X);
label("A", A, SE);
label("Z", Z, dir(270));
label("X", X, dir(270));
label("C", C, SW);
label("S", S, NW);
label("P", P, dir(45));
label("1", (S+Z)/2, E);
label("1", (X+P)/2, E);
label("2", (S+P)/2, N);
draw((1.732,.15)--(1.882,.15)--(1.882,0));
draw((3.732,.15)--(3.582,.15)--(3.582,0));
label("$30^\circ$", (.35,.15), E);
label("$45^\circ$", (4.5,.15), W);
